import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { createHash } from "node:crypto";
import * as Sha256 from "../core/res/PwSha256.res.mjs";
import * as Codec from "../core/res/PwCodec.res.mjs";

// T008 / AC10, AC15: closed wire schema v1 (specs/001-core-foundation/contracts/wire-v1.md), canonical
// bytes, hashes and strict decoding. The examples in test/fixtures/wire are generated by
// scripts/wire-examples.py from the data model, independent of the ReScript core; their SHA-256 values
// are computed there, and the SHA-256 implementation is also compared with node:crypto.
const dir = new URL("./fixtures/wire/", import.meta.url);
const text = (name) => readFileSync(new URL(name, dir), "utf8");
const index = JSON.parse(text("index.json"));
const ok = (r) => { assert.equal(r.TAG, "Ok", `expected Ok, got ${JSON.stringify(r)}`); return r._0; };
const fails = (r, code, path) => {
  assert.equal(r.TAG, "Error", `expected Error ${code} ${path}, got Ok`);
  assert.deepEqual([r._0.code, r._0.path], [code, path]);
};
const def2 = ok(Codec.decodeDefinition(text("definition-2.json")));
const def3 = ok(Codec.decodeDefinition(text("definition-3.json")));
const edit = (name, fn) => { const o = JSON.parse(text(name)); fn(o); return JSON.stringify(o); };
const state2 = (fn) => Codec.decodeState(def2, edit("state-2-home.json", fn));
const definition2 = (fn) => Codec.decodeDefinition(edit("definition-2.json", fn));

test("SHA-256 matches the FIPS 180-4 vectors", () => {
  assert.equal(Sha256.hex(""), "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855");
  assert.equal(Sha256.hex("abc"), "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad");
  assert.equal(Sha256.hex("abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq"), "248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1");
  assert.equal(Sha256.hex("a".repeat(1000000)), "cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0");
});

test("SHA-256 equals node:crypto around every padding boundary", () => {
  for (let n = 0; n <= 200; n++) {
    const s = "x".repeat(n);
    assert.equal(Sha256.hex(s), createHash("sha256").update(s, "ascii").digest("hex"), `length ${n}`);
  }
});

test("canonical bytes and hashes of all examples equal the independently generated ones", () => {
  const cases = [
    ["definition-2.json", def2, Codec.encodeDefinition, Codec.hashDefinition],
    ["definition-3.json", def3, Codec.encodeDefinition, Codec.hashDefinition],
  ];
  for (const [name, d, enc, hash] of cases) {
    assert.equal(enc(d), text(name), name);
    assert.equal(hash(d), index[name].sha256, name);
    assert.equal(text(name).length, index[name].bytes);
  }
  const states = [["state-2-home.json", def2], ["state-2-scrambled.json", def2], ["state-3-home.json", def3], ["state-3-scrambled.json", def3]];
  for (const [name, d] of states) {
    const s = ok(Codec.decodeState(d, text(name)));
    assert.equal(Codec.encodeState(s), text(name), name);
    assert.equal(Codec.hashState(s), index[name].sha256, name);
  }
});

test("decoding is lossless: decode, encode, decode again gives identical bytes", () => {
  const s = ok(Codec.decodeState(def3, text("state-3-scrambled.json")));
  const again = ok(Codec.decodeState(def3, Codec.encodeState(s)));
  assert.equal(Codec.encodeState(again), Codec.encodeState(s));
  assert.equal(Codec.hashState(again), Codec.hashState(s));
});

test("whitespace and array order do not change the canonical form or the hash", () => {
  const o = JSON.parse(text("state-3-scrambled.json"));
  o.poses.reverse();
  const messy = JSON.stringify(o, null, 4).replace(/\n/g, "\r\n");
  const s = ok(Codec.decodeState(def3, messy));
  assert.equal(Codec.encodeState(s), text("state-3-scrambled.json"));
  const d = JSON.parse(text("definition-2.json"));
  d.pieces.reverse();
  for (const p of d.pieces) p.stickers.reverse();
  assert.equal(Codec.encodeDefinition(ok(Codec.decodeDefinition(JSON.stringify(d, null, 1)))), text("definition-2.json"));
});

test("a different state has a different hash; ids and definitions are part of the hash input", () => {
  const home = ok(Codec.decodeState(def2, text("state-2-home.json")));
  const scr = ok(Codec.decodeState(def2, text("state-2-scrambled.json")));
  assert.notEqual(Codec.hashState(home), Codec.hashState(scr));
  assert.notEqual(Codec.hashDefinition(def2), Codec.hashDefinition(def3));
  assert.match(Codec.hashState(home), /^sha256:[0-9a-f]{64}$/);
});

test("the centers of the scrambled 3x3 carry their pose", () => {
  const u = JSON.parse(text("state-3-scrambled.json")).poses.find((p) => p.pieceId === "U");
  // U and U' cancel on the center; Rw and x each turn it by Rx(-1): a half turn about X, from (0,2,0) to (0,-2,0).
  assert.deepEqual(u.position, [0, -2, 0]);
  assert.deepEqual(u.orientation, [1, 0, 0, 0, -1, 0, 0, 0, -1]);
});

test("syntax errors, trailing data, BOM and top-level type", () => {
  const good = text("state-2-home.json");
  fails(Codec.decodeState(def2, ""), "Syntax", "$");
  fails(Codec.decodeState(def2, "{"), "Syntax", "$");
  fails(Codec.decodeState(def2, good + "x"), "Syntax", "$");
  fails(Codec.decodeState(def2, good + " {}"), "Syntax", "$");
  fails(Codec.decodeState(def2, "﻿" + good), "Syntax", "$");
  fails(Codec.decodeState(def2, good.replace('"revision":1', '"revision":1,')), "Syntax", "$");
  fails(Codec.decodeState(def2, good.replace(/"/g, "'")), "Syntax", "$");
  fails(Codec.decodeState(def2, "[]"), "WrongType", "$");
  fails(Codec.decodeState(def2, "null"), "WrongType", "$");
});

test("duplicate keys, negative zero, fractions, exponents and unsafe integers are rejected", () => {
  const good = text("state-2-home.json");
  fails(Codec.decodeState(def2, good.replace('"revision":1', '"revision":1,"revision":1')), "DuplicateKey", "$.revision");
  fails(Codec.decodeState(def2, good.replace('"position":[-1,-1,-1]', '"position":[-1,-1,-1,0],"position":[-1,-1,-1]')), "DuplicateKey", "$.poses[0].position");
  fails(Codec.decodeState(def2, good.replace('"position":[-1,-1,-1]', '"position":[-0,-1,-1]')), "NegativeZero", "$.poses[0].position[0]");
  fails(Codec.decodeState(def2, good.replace('"position":[-1,-1,-1]', '"position":[-1.0,-1,-1]')), "NotInteger", "$.poses[0].position[0]");
  fails(Codec.decodeState(def2, good.replace('"position":[-1,-1,-1]', '"position":[-1,-1e0,-1]')), "NotInteger", "$.poses[0].position[1]");
  fails(Codec.decodeState(def2, good.replace('"position":[-1,-1,-1]', '"position":[-1,-1,-9007199254740993]')), "NotInteger", "$.poses[0].position[2]");
});

test("input size and nesting are bounded", () => {
  fails(Codec.decodeState(def2, " ".repeat(16 * 1024 * 1024 + 1)), "TooLarge", "$");
  fails(Codec.decodeState(def2, "[".repeat(65) + "]".repeat(65)), "TooDeep", "$");
  fails(Codec.decodeState(def2, '{"a":'.repeat(65) + "1" + "}".repeat(65)), "TooDeep", "$");
  fails(Codec.decodeState(def2, "[".repeat(64) + "]".repeat(64)), "WrongType", "$");
});

test("the schema is closed: missing and unknown fields, schema name and revision", () => {
  fails(state2((o) => delete o.schema), "MissingField", "$.schema");
  fails(state2((o) => delete o.poses[0].pieceId), "MissingField", "$.poses[0].pieceId");
  fails(state2((o) => (o.extra = 1)), "UnknownField", "$.extra");
  fails(state2((o) => (o.poses[2].x = 0)), "UnknownField", "$.poses[2].x");
  fails(state2((o) => (o.schema = "puzlwerk.definition")), "BadSchema", "$.schema");
  fails(state2((o) => (o.revision = 2)), "BadRevision", "$.revision");
  fails(state2((o) => (o.revision = "1")), "WrongType", "$.revision");
  fails(state2((o) => (o.revision = true)), "WrongType", "$.revision");
  fails(state2((o) => (o.poses = {})), "WrongType", "$.poses");
  fails(state2((o) => (o.poses[0].position = "1,1,1")), "WrongType", "$.poses[0].position");
  fails(state2((o) => (o.poses[0].orientation[3] = "0")), "WrongType", "$.poses[0].orientation[3]");
  fails(state2((o) => (o.poses[0].position = [1, 1])), "BadValue", "$.poses[0].position");
  fails(state2((o) => (o.poses[0].pieceId = null)), "WrongType", "$.poses[0].pieceId");
});

test("state: ids, definition link, completeness and duplicates", () => {
  fails(state2((o) => (o.poses[0].pieceId = "bad id")), "BadId", "$.poses[0].pieceId");
  fails(state2((o) => (o.poses[0].pieceId = "")), "BadId", "$.poses[0].pieceId");
  fails(state2((o) => (o.definitionId = "cube3")), "DefinitionMismatch", "$.definitionId");
  fails(state2((o) => (o.poses[1].pieceId = o.poses[0].pieceId)), "DuplicateId", "$.poses[1].pieceId");
  fails(state2((o) => (o.poses[0].pieceId = "ZZZ")), "PieceMismatch", "$.poses[0].pieceId");
  fails(state2((o) => o.poses.pop()), "PieceMismatch", "$.poses");
  fails(Codec.decodeState(def3, text("state-2-home.json")), "DefinitionMismatch", "$.definitionId");
});

test("state: positions, orientations and the position rule", () => {
  fails(state2((o) => (o.poses[0].position = [0, 0, 0])), "BadValue", "$.poses[0].position");
  fails(state2((o) => (o.poses[0].position = [2, 1, 1])), "BadValue", "$.poses[0].position");
  fails(state2((o) => (o.poses[0].orientation = [-1, 0, 0, 0, 1, 0, 0, 0, 1])), "BadOrientation", "$.poses[0].orientation");
  fails(state2((o) => (o.poses[0].orientation = [2, 0, 0, 0, 1, 0, 0, 0, 1])), "BadOrientation", "$.poses[0].orientation");
  fails(state2((o) => (o.poses[0].orientation = [1, 0, 0, 0, 1, 0, 0, 0])), "BadValue", "$.poses[0].orientation");
  // swap the positions of two pieces: both are shell slots, but p != O.home.
  fails(state2((o) => { const t = o.poses[0].position; o.poses[0].position = o.poses[1].position; o.poses[1].position = t; }), "PositionRule", "$.poses[0]");
  // DBR (home 1,-1,-1) turned by +Y lands on (-1,-1,-1), the slot of DBL: the rule holds, the slot is taken.
  fails(state2((o) => { o.poses[1].orientation = [0, 0, 1, 0, 1, 0, -1, 0, 0]; o.poses[1].position = [-1, -1, -1]; }), "DuplicateSlot", "$.poses[1].position");
});

test("definition: size, convention, move policy and ids", () => {
  fails(definition2((o) => (o.size = 1)), "BadValue", "$.size");
  fails(definition2((o) => (o.size = 65)), "BadValue", "$.size");
  fails(definition2((o) => (o.size = "2")), "WrongType", "$.size");
  fails(definition2((o) => (o.convention = "other")), "BadValue", "$.convention");
  fails(definition2((o) => (o.movePolicy = "all")), "BadValue", "$.movePolicy");
  fails(definition2((o) => (o.id = "a b")), "BadId", "$.id");
  fails(definition2((o) => (o.schema = "puzlwerk.state")), "BadSchema", "$.schema");
  fails(definition2((o) => (o.extra = 1)), "UnknownField", "$.extra");
  fails(definition2((o) => (o.pieces[0].stickers[0].extra = 1)), "UnknownField", "$.pieces[0].stickers[0].extra");
  fails(definition2((o) => (o.pieces[0].stickers[0].color = "red!")), "BadId", "$.pieces[0].stickers[0].color");
});

test("definition: catalog completeness and uniqueness", () => {
  fails(definition2((o) => (o.pieces[1].id = o.pieces[0].id)), "DuplicateId", "$.pieces[1].id");
  fails(definition2((o) => (o.pieces[1].stickers[0].id = o.pieces[0].stickers[0].id)), "DuplicateId", "$.pieces[1].stickers[0].id");
  fails(definition2((o) => (o.pieces[0].home = [0, 1, 1])), "BadValue", "$.pieces[0].home");
  fails(definition2((o) => (o.pieces[1].home = o.pieces[0].home)), "DuplicateSlot", "$.pieces[1].home");
  fails(definition2((o) => o.pieces.pop()), "PieceMismatch", "$.pieces");
  fails(Codec.decodeDefinition(JSON.stringify({ ...JSON.parse(text("definition-2.json")), size: 3 })), "BadValue", "$.pieces[0].home");
});

test("definition: stickers cover exactly the exposed faces with a perpendicular unit up", () => {
  fails(definition2((o) => (o.pieces[0].stickers[0].normal = [0, 1, 0])), "BadSticker", "$.pieces[0].stickers[0].normal");
  fails(definition2((o) => (o.pieces[0].stickers[0].normal = [0, 0, -2])), "BadSticker", "$.pieces[0].stickers[0].normal");
  fails(definition2((o) => o.pieces[0].stickers.pop()), "BadSticker", "$.pieces[0].stickers");
  fails(definition2((o) => (o.pieces[0].stickers[1].normal = o.pieces[0].stickers[0].normal)), "BadSticker", "$.pieces[0].stickers[1].normal");
  fails(definition2((o) => (o.pieces[0].stickers[0].up = o.pieces[0].stickers[0].normal)), "BadSticker", "$.pieces[0].stickers[0].up");
  fails(definition2((o) => (o.pieces[0].stickers[0].up = [0, 1, 1])), "BadSticker", "$.pieces[0].stickers[0].up");
  // perpendicular to the normal (0,0,-1) but not a unit vector
  fails(definition2((o) => (o.pieces[0].stickers[0].up = [0, 2, 0])), "BadSticker", "$.pieces[0].stickers[0].up");
});

test("integers outside the 32-bit range fail instead of decoding as 0 (10 to 15 digits)", () => {
  const good = text("state-2-home.json");
  const withPosition = (v) => good.replace('"position":[-1,-1,-1]', `"position":${v}`);
  for (const digits of [10, 11, 12, 13, 14, 15]) {
    const big = "9".repeat(digits);
    fails(Codec.decodeState(def2, withPosition(`[${big},-1,-1]`)), "NotInteger", "$.poses[0].position[0]");
    fails(Codec.decodeState(def2, withPosition(`[-1,-${big},-1]`)), "NotInteger", "$.poses[0].position[1]");
  }
  fails(Codec.decodeState(def2, withPosition("[10000000000,2147483648,-2147483649]")), "NotInteger", "$.poses[0].position[0]");
  fails(Codec.decodeState(def2, withPosition("[-1,2147483648,-1]")), "NotInteger", "$.poses[0].position[1]");
  fails(Codec.decodeState(def2, withPosition("[-1,-1,-2147483649]")), "NotInteger", "$.poses[0].position[2]");
  // the largest and smallest int32 values still parse; they are not shell slots
  fails(Codec.decodeState(def2, withPosition("[2147483647,-1,-1]")), "BadValue", "$.poses[0].position");
  fails(Codec.decodeState(def2, withPosition("[-2147483648,-1,-1]")), "BadValue", "$.poses[0].position");
  // a 3x3 state with a huge coordinate is rejected
  const s3 = text("state-3-home.json").replace('"position":[-2,-2,-2]', '"position":[10000000000,-2,-2]');
  fails(Codec.decodeState(def3, s3), "NotInteger", "$.poses[5].position[0]");
});

test("\\u escapes need exactly four hex digits", () => {
  const good = text("state-2-home.json");
  const withDefinitionId = (escape) => good.replace('"definitionId":"cube2"', `"definitionId":"${escape}"`);
  for (const bad of ["\\u41zz", "\\u0x41", "\\u 041", "\\u+041", "\\u-041", "\\u004", "\\u00", "\\u004G", "\\u00 1"]) {
    fails(Codec.decodeState(def2, withDefinitionId(`cub${bad}`)), "Syntax", "$");
  }
  // valid escapes decode: c is "c", C is "C" (a different ID)
  assert.equal(Codec.decodeState(def2, withDefinitionId("\\u0063ube2")).TAG, "Ok");
  assert.equal(Codec.decodeState(def2, withDefinitionId("\\u0063ub\\u0065\\u0032")).TAG, "Ok");
  fails(Codec.decodeState(def2, withDefinitionId("\\u0043ube2")), "DefinitionMismatch", "$.definitionId");
  // upper- and lowercase hex digits are both valid: \u004A is "J", \u004a is "J"
  fails(Codec.decodeState(def2, withDefinitionId("\\u004Aube2")), "DefinitionMismatch", "$.definitionId");
  fails(Codec.decodeState(def2, withDefinitionId("\\u004aube2")), "DefinitionMismatch", "$.definitionId");
});
